mapper.select:
select
  /* 활성 회원: enddate 안 지난 바우처 보유자(필요 시 startdate 조건 추가) */
  (select count(distinct v.memnum)
     from voucher_log v
    where v.enddate >= curdate()
  ) as activemembers,

  /* 이번 달 신규 가입: member.memcreated 기준 */
  (select count(*)
     from member m
    where m.memcreated >= date_format(now(), '%Y-%m-01')
      and m.memcreated < date_add(date_format(now(), '%Y-%m-01'), interval 1 month)
  ) as monthnewmembers,

  /* 월 누적 매출: 서비스(actualamount) + 아이템(totalamount) */
  (
    ifnull( (select sum(s.actualamount)
            from sales_service s
           where s.createdat >= date_format(now(), '%Y-%m-01')
             and s.createdat < date_add(date_format(now(), '%Y-%m-01'), interval 1 month)
        ), 0)
    +
    ifnull( (select sum(i.totalamount)
            from sales_item i
           where i.createdat >= date_format(now(), '%Y-%m-01')
             and i.createdat < date_add(date_format(now(), '%Y-%m-01'), interval 1 month)
        ), 0)
  ) as mtdrevenue
